nt?.pause()}>Pause</button></div>{view?.state.ended && <Link href="/" className="back-link">Find another adventure →</Link>}</section></div><div className="interaction-bar"><span className="mic-symbol">✧</span><form onSubmit={e => { e.preventDefault(); if (text.trim()) { void session.current?.turn(text.trim()); setText(""); } }}><label htmlFor="story-idea">{view?.listening ? "Your microphone is on. Jump in anytime!" : "A little idea can change everything."}</label><div className="input-row"><input id="story-idea" value={text} maxLength={600} onChange={e => setText(e.target.value)} placeholder='Try “The tortoise has roller skates!”'/><button type="submit" aria-label="Add your idea" disabled={!text.trim()}>↑</button></div></form><p>Talk to a character.<br/>Dream up a twist.<br/>Make it yours.</p></div>{view?.error && <p className="error" role="alert">{view.error}</p>}{notice && <p className="notice" role="status">{notice} <Link href="/adventures">My adventures →</Link></p>}<details className="transcript"><summary>Our adventure so far</summary>{view?.state.log.map((e,i) => <p key={i}><strong>{e.kind === "child" ? "You" : e.speaker}:</strong> {e.text}</p>)}</details></main>;
}

